UPDATE pull_task_member_query
SET command_id = #{commandId},
    updated_at = #{now}
WHERE id = #{id}
  AND query_status = #{expectedStatus}
  AND command_id IS NULL

UPDATE pull_task_member_query
SET query_status = #{targetStatus},
    completed_at = #{now},
    error_code = #{errorCode},
    error_message = #{errorMessage},
    updated_at = #{now}
WHERE id = #{id}
  AND query_status = #{expectedStatus}
  AND deadline_at <= #{now}

UPDATE pull_task_member_query
SET query_status = #{targetStatus},
    completed_at = #{now},
    error_code = #{errorCode},
    error_message = #{errorMessage},
    updated_at = #{now}
WHERE task_id = #{taskId}

    AND group_execution_id = #{groupExecutionId}

  AND query_status = #{expectedStatus}

UPDATE pull_task_member_query
SET query_status = #{settlement.targetStatus},
    result_json = #{settlement.resultJson},
    completed_at = #{settlement.completedAt},
    error_code = #{settlement.errorCode},
    error_message = #{settlement.errorMessage},
    updated_at = #{settlement.completedAt}
WHERE id = #{settlement.queryId}
  AND command_id = #{settlement.commandId}
  AND query_status = #{settlement.expectedStatus}
